LOGIN_HTML = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width">
<title>Log in - Coding AI</title><style>""" + AUTH_CSS + r"""</style></head><body><main class="card"><h1>Log in</h1>
<form id="form"><label for="username">Username or email</label><input id="username" autocomplete="username" required>
<label for="password">Password</label><input id="password" type="password" autocomplete="current-password" required>
<p class="field-link"><a href="/forgot-password">Forgot password?</a></p>
<button id="submit">Log in</button></form><p class="message" id="message" role="alert"></p>
<p>Need an account? <a href="/register">Register here</a>.</p></main><script>
const form=document.querySelector('#form'),statusMessage=document.querySelector('#message'),submit=document.querySelector('#submit');let countdownTimer=null;
function startCountdown(seconds,message){clearInterval(countdownTimer);const endsAt=Date.now()+Math.max(1,seconds)*1000;submit.disabled=true;statusMessage.classList.add('countdown');const update=()=>{const remaining=Math.max(0,Math.ceil((endsAt-Date.now())/1000));if(!remaining){clearInterval(countdownTimer);countdownTimer=null;statusMessage.classList.remove('countdown');statusMessage.textContent='You can try to log in again.';submit.disabled=false;return}const minutes=Math.floor(remaining/60),secs=remaining%60;statusMessage.textContent=message+' Try again in '+String(minutes).padStart(2,'0')+':'+String(secs).padStart(2,'0')+'.'};update();countdownTimer=setInterval(update,250)}
form.onsubmit=async e=>{e.preventDefault();if(countdownTimer)return;submit.disabled=true;statusMessage.textContent='Logging in...';try{const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:document.querySelector('#username').value,password:document.querySelector('#password').value})});const data=await r.json();if(r.status===403){location.href='/forbidden';return}if(!r.ok){const retryAfter=Number(r.headers.get('Retry-After'))||0;if(retryAfter>0){startCountdown(retryAfter,typeof data.detail==='string'?data.detail:'Login temporarily unavailable.');return}throw Error(data.detail||r.statusText)}location.href='/'}catch(err){statusMessage.textContent=err.message;submit.disabled=false}};
</script></body></html>"""


